/usr/bin/bash -lc "python - <<'PY'
import urllib.request
url='https://arxiv.org/pdf/1904.10482v1'
try:
    with urllib.request.urlopen(url,timeout=20) as r:
        b=r.read()
    print(len(b),b[:80])
    try:
        import pymupdf
        d=pymupdf.open(stream=b,filetype='pdf')
        for i,p in enumerate(d):
            t=p.get_text()
            if '3.30' in t or 'low power' in t:
                print('PAGE',i+1,t)
    except ImportError:
        import io
        from pypdf import PdfReader
        d=PdfReader(io.BytesIO(b))
        for i,p in enumerate(d.pages):
            t=p.extract_text()
            if '3.30' in t or 'low power' in t:
                print('PAGE',i+1,t)
except Exception as e:
    print(type(e).__name__,str(e))
PY"
